-- =====================================================================
-- 0072 — HRM & Payroll (a new KMR App, built from scratch like Minutes Of Meetings)
--  • Employees with salary structure, shifts, holiday calendar, leave types and leave requests.
--  • Attendance entered by hand OR taken from fingerprint / face / card machines (eSSL, ZKTeco, Realtime and other makes:
--    machine push, universal JSON push, or a file exported from the machine).
--  • Automated monthly payroll from attendance: earnings, PF, ESI, professional tax, overtime, payslips, bank and statutory files.
--  • Sample data (employees, a month of punches, leave) to validate the flow and delete again.
-- The earlier HRM (schema "hrm", its own repository) is switched off: its data is NOT touched, and each company that had it
-- gets the new app on the same licence (old company ids are kept in console.hrms_legacy for a later clean-up).
-- Needs 0069 (KMR CAD Draft). Safe to re-run. Generated by scripts/make-hrms.py.
-- =====================================================================
do $$ begin
  if to_regprocedure('console.cad_sample(uuid, text)') is null then raise exception 'Run 0069_cad_draft.sql first.'; end if;
end $$;

insert into console.products (code, name, description, app_path, seat_label, current_version, sort_order) values
  ('hrms', 'HRM & Payroll', 'Employees, shifts, attendance by hand or fingerprint / face machines, leave and automated payroll with payslips', '/it/hrm.html', 'employees', '1.0.0', 11)
on conflict (code) do nothing;
update console.products set active = false where code = 'hrm';        -- the earlier HRM is switched off (its data stays in the database)
insert into console.releases (product_code, version, notes) values
  ('hrms', '1.0.0', 'HRM & Payroll: employees, shifts, holidays, manual and biometric attendance (eSSL, ZKTeco, Realtime, universal push and file import), leave, automated payroll, payslips') on conflict do nothing;
insert into console.prices (product_code, period, currency, unit_amount, min_seats, active, note)
select 'hrms', p.period, p.currency, p.unit_amount, p.min_seats, p.active, 'Copied from the earlier HRM (0072) — change in Console › Billing'
  from console.prices p where p.product_code = 'hrm'
on conflict (product_code, period, currency) do nothing;
insert into console.prices (product_code, period, currency, unit_amount, min_seats, active, note)
select v.code, v.period, 'INR', v.amt, 25, true, 'Starting price list (0072) — per employee, change in Console › Billing'
  from (values ('hrms', 'month', 60), ('hrms', 'year', 600)) v(code, period, amt)
 where not exists (select 1 from console.prices x where x.product_code = 'hrms' and x.currency = 'INR' and x.period = v.period)
on conflict (product_code, period, currency) do nothing;
insert into public.app_listings (code, name, tagline, features, sort_order, is_active) values
  ('hrms', 'HRM & Payroll', 'Employees, attendance from fingerprint and face machines, leave and payroll that works itself out each month.',
   E'Attendance by hand or from eSSL, ZKTeco, Realtime and other fingerprint / face machines\nShifts, holidays and leave with approvals\nAutomated payroll: PF, ESI, professional tax, overtime, payslips and bank file', 10, true)
on conflict (code) do update set name = excluded.name, tagline = excluded.tagline, features = excluded.features, is_active = true;
update public.app_listings set is_active = false where code = 'hrm';

insert into console.app_features (product_code, name, detail, is_core, price_month, price_year, setup_fee, sort_order) values
  ('hrms', 'Employees & shifts', 'Employee master with salary structure, shifts, holiday calendar and dashboard', true, 15, 0, 10000, 10),
  ('hrms', 'Attendance', 'Manual attendance entry, daily status, late and overtime, monthly attendance sheet', false, 10, 0, 5000, 20),
  ('hrms', 'Biometric machines', 'Fingerprint, face and card machines: eSSL, ZKTeco, Realtime and other makes by machine push, universal push or file import', false, 10, 0, 10000, 30),
  ('hrms', 'Leave', 'Leave types, balances, requests and approval', false, 5, 0, 3000, 40),
  ('hrms', 'Automated payroll', 'Monthly payroll from attendance: earnings, PF, ESI, professional tax, overtime, payslips, bank and statutory files', false, 20, 0, 15000, 50)
on conflict (product_code, name) do nothing;
delete from console.app_features f where f.product_code = 'hrms' and f.name = 'Core platform'
   and not exists (select 1 from console.invoice_lines il where il.feature_id = f.id);
update console.app_features set price_year = price_month * 10 where product_code = 'hrms' and price_year = 0;
select console.sync_app_price('hrms');

-- ---------- tables ----------
create table if not exists console.hrms_counters (
  customer_id uuid not null references console.customers(id) on delete cascade, key text not null, n bigint not null default 0, sample boolean not null default false, primary key (customer_id, key));
create table if not exists console.hrms_settings (
  customer_id uuid primary key references console.customers(id) on delete cascade, data jsonb not null default '{}', sample boolean not null default false, updated_at timestamptz not null default now());
create table if not exists console.hrms_shifts (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  name text not null, start_time text not null default '09:00', end_time text not null default '18:00', grace_min int not null default 10, break_min int not null default 30,
  half_day_min int not null default 240, full_day_min int not null default 450, night boolean not null default false, weekly_off int[] not null default '{0}',
  active boolean not null default true, sample boolean not null default false, created_at timestamptz not null default now(), unique (customer_id, name));
create table if not exists console.hrms_holidays (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  hdate date not null, name text not null, sample boolean not null default false, unique (customer_id, hdate));
create table if not exists console.hrms_leave_types (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  code text not null, name text not null, paid boolean not null default true, annual_quota numeric(5,1) not null default 0, active boolean not null default true,
  sample boolean not null default false, unique (customer_id, code));
create table if not exists console.hrms_devices (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  name text not null, vendor text not null default 'eSSL / ZKTeco', model text, modes text[] not null default '{finger}', serial text, protocol text not null default 'adms' check (protocol in ('adms', 'json', 'file')),
  location text, ip text, push_key text not null default replace(gen_random_uuid()::text, '-', ''), enabled boolean not null default true,
  last_seen timestamptz, last_punch timestamptz, punches_total bigint not null default 0, notes text,
  sample boolean not null default false, created_at timestamptz not null default now());
create unique index if not exists hrms_dev_serial on console.hrms_devices (lower(serial)) where serial is not null;
create unique index if not exists hrms_dev_key on console.hrms_devices (push_key);
create table if not exists console.hrms_employees (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  emp_code text not null, name text not null, gender text, dob date, doj date, dol date, department text, designation text, grade text, mobile text, email text, address text,
  status text not null default 'active' check (status in ('active', 'left')), shift_id uuid references console.hrms_shifts(id) on delete set null, bio_id text,
  pay_type text not null default 'monthly' check (pay_type in ('monthly', 'daily')),
  basic numeric(12,2) not null default 0, hra numeric(12,2) not null default 0, special numeric(12,2) not null default 0, other_allow numeric(12,2) not null default 0,
  pf boolean not null default false, esi boolean not null default false, pt boolean not null default false, ot_eligible boolean not null default false,
  uan text, esi_no text, pan text, bank_name text, bank_account text, ifsc text, notes text,
  sample boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (customer_id, emp_code));
create unique index if not exists hrms_emp_bio on console.hrms_employees (customer_id, bio_id) where bio_id is not null and bio_id <> '';
create table if not exists console.hrms_punches (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  device_id uuid references console.hrms_devices(id) on delete set null, employee_id uuid references console.hrms_employees(id) on delete cascade, bio_id text not null,
  punched_at timestamptz not null, verify text not null default 'other', direction text check (direction in ('in', 'out')), source text not null default 'device' check (source in ('device', 'json', 'import', 'manual')),
  sample boolean not null default false, created_by text, created_at timestamptz not null default now(), unique (customer_id, bio_id, punched_at));
create index if not exists hrms_pun_time on console.hrms_punches (customer_id, punched_at);
create table if not exists console.hrms_attendance (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  employee_id uuid not null references console.hrms_employees(id) on delete cascade, work_date date not null,
  in_at timestamptz, out_at timestamptz, worked_min int not null default 0, late_min int not null default 0, early_min int not null default 0, ot_min int not null default 0,
  status text not null check (status in ('P', 'HD', 'A', 'L', 'U', 'WO', 'H', 'MP')), leave_code text, source text not null default 'punch' check (source in ('punch', 'manual', 'leave', 'rule')),
  remarks text, sample boolean not null default false, updated_by text, updated_at timestamptz not null default now(), unique (employee_id, work_date));
create index if not exists hrms_att_date on console.hrms_attendance (customer_id, work_date);
create table if not exists console.hrms_leaves (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  employee_id uuid not null references console.hrms_employees(id) on delete cascade, leave_type_id uuid references console.hrms_leave_types(id) on delete set null, leave_code text,
  from_date date not null, to_date date not null, half boolean not null default false, days numeric(5,1) not null default 1, reason text,
  status text not null default 'Pending' check (status in ('Pending', 'Approved', 'Rejected', 'Cancelled')), decided_by text, decided_at timestamptz,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now());
create index if not exists hrms_leave_emp on console.hrms_leaves (customer_id, employee_id, from_date);
create table if not exists console.hrms_payroll_runs (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  period text not null check (period ~ '^\d{4}-\d{2}$'), status text not null default 'draft' check (status in ('draft', 'final')), month_days int not null default 30,
  totals jsonb not null default '{}', note text, finalised_by text, finalised_at timestamptz,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (customer_id, period));
create table if not exists console.hrms_payslips (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  run_id uuid not null references console.hrms_payroll_runs(id) on delete cascade, employee_id uuid references console.hrms_employees(id) on delete set null,
  emp_code text not null, emp_name text not null, department text, designation text, paid_days numeric(5,1) not null default 0, lop_days numeric(5,1) not null default 0, ot_hours numeric(6,2) not null default 0,
  earnings jsonb not null default '[]', deductions jsonb not null default '[]', gross numeric(12,2) not null default 0, deduct numeric(12,2) not null default 0, net numeric(12,2) not null default 0,
  info jsonb not null default '{}', sample boolean not null default false, unique (run_id, emp_code));
create table if not exists console.hrms_legacy (
  customer_id uuid primary key references console.customers(id) on delete cascade, tenant_id uuid not null, tenant_slug text, moved_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['hrms_counters','hrms_settings','hrms_shifts','hrms_holidays','hrms_leave_types','hrms_devices','hrms_employees','hrms_punches','hrms_attendance','hrms_leaves','hrms_payroll_runs','hrms_payslips','hrms_legacy'] loop
  execute format('alter table console.%I enable row level security', t);
  execute format('drop policy if exists %I on console.%I', t || '_staff', t);
  execute format('create policy %I on console.%I for all to authenticated using (console.is_staff()) with check (console.is_staff())', t || '_staff', t);
end loop; end $$;

-- ---------- the earlier HRM is switched off; companies that had it get the new app on the same licence ----------
do $$ begin
  if to_regclass('hrm.tenants') is not null then
    insert into console.hrms_legacy (customer_id, tenant_id, tenant_slug)
    select l.customer_id, l.product_ref, (select t.slug from hrm.tenants t where t.id = l.product_ref) from console.licences l where l.product_code = 'hrm' and l.product_ref is not null
    on conflict (customer_id) do nothing;
  else
    insert into console.hrms_legacy (customer_id, tenant_id) select l.customer_id, l.product_ref from console.licences l where l.product_code = 'hrm' and l.product_ref is not null on conflict (customer_id) do nothing;
  end if;
end $$;
insert into console.licences (customer_id, product_code, status, valid_until, seats, notes, product_ref, product_slug)
select l.customer_id, 'hrms', l.status, l.valid_until, l.seats, 'Moved from the earlier HRM (0072)', l.customer_id, c.slug
  from console.licences l join console.customers c on c.id = l.customer_id where l.product_code = 'hrm'
on conflict (customer_id, product_code) do nothing;
-- the earlier licence stays (invoices, history) but no longer points at a company inside the old HRM, so nothing reads or writes the old data any more
update console.licences set product_ref = null where product_code = 'hrm' and product_ref is not null;
update console.customer_members m set roles = (m.roles - 'hrm') || jsonb_build_object('hrms', case m.roles ->> 'hrm'
        when 'company_admin' then 'admin' when 'hr_manager' then 'editor' when 'hr_executive' then 'editor' when 'payroll' then 'editor' else 'viewer' end)
 where m.roles ? 'hrm' and coalesce(m.roles ->> 'hrm', '') <> '' and not (m.roles ? 'hrms') and m.roles ->> 'hrm' <> 'employee'
   and exists (select 1 from console.licences l where l.customer_id = m.customer_id and l.product_code = 'hrms');


